\noindent The explicit models, which we construct are of product form
\eq{\label{ansatz}
\left(\overline M,\mathbf g\right)=\left(I\times M_1\times M_2,-dt^2+a(t)^2 g_1+b(t)^2g_2\right),
}
where $g_1$ and $g_2$ are Einstein metrics, i.e.~$\mathrm {Ric}[g_i]=\lambda_i g_i$ for $i=1,2$ and constants $\lambda_i$.

\label{thm-1}
Let $\Lambda=\frac{n(n-1)}{2}$ and let $M_1$, $M_2$ be closed manifolds of  dimension $\dim M_i=n_i\geq 2$, $n_1+n_2=n$. Consider initial data of the form $x(0)=y(0)=\dot x(0)=\dot y(0)=0$ such that
\eq{\label{eq-def-rel}
n(n-1)=n_1\lambda_1+n_2\lambda_2,
}
holds. Then the following cases occur.
\begin{enumerate}

\item If $\lambda_2>n$ and $\lambda_1<(n_1-1)n/n_1$, the MGHD recollapses, i.e.~is future- and past incomplete, $I=(t_-,t_+)$ for $t_-<0<t_+$. Both singularities are of Kasner-type, i.e.~one factor collapses and the other factor has unbounded volume as $t\rightarrow t_{\pm}$. The mean curvature $H\rightarrow \pm\infty$ as $t\rightarrow t_{\pm}$. The Kretschmann scalar is unbounded towards both singularities. In particular, the MGHDs are $C^2$-inextendible.

\item If $\lambda_2=n$ and $\lambda_1=(n_1-1)n/n_1$, MGHD is 
\eq{\label{crit-sol}
\left(\mathbb R\times M_1\times M_2,-dt^2+\cosh\left(\sqrt{\frac{n}{n_1}}t\right)^2\cdot g_1 + g_2\right),
}
and in particular future and past complete.
\item If $n(n_1-1)/n_1<\lambda_1<(n-1)$ or equivalently $n-1<\lambda_2<n$ the MGHD is future- and past complete. In both time directions, both factors expand exponentially with asymptotic growth rates depending only on the dimensions $n_1$ and $n_2$. 
\end{enumerate}
Furthermore, the behavior is stable in the following sense. Initial data induced by any recollapsing solution in the class above has an open\footnote{Here, open is meant in the sense of $(g,K)\in H^\ell\times H^{\ell-1}$ spaces with $\ell=\ell(n)$ sufficiently large, where $(g,K)$ denote the spatial metric and second fundamental form, respectively.} neighborhood in the initial-data manifold, such that the MGHD of each element in this neighborhood recollapses. Similarly, initial data induced by any complete solution (except the critical solution) has an open neighborhood with elements that give rise to complete MGHDs. The critical solution \eqref{crit-sol} is unstable.

The case $\lambda_1=\lambda_2=n-1$ corresponds to the background solution
\eq{
-dt^2+ \cosh(t)^2 \cdot (g_1+g_2).
} 
If $\lambda_2<\lambda_1$ we divide into three subcases that relate to the previous cases by interchanging $\lambda_1$ and $\lambda_2$ (and $n_1$ and $n_2$) in the statements of the theorem.

The Nariai solution
\eq{
-dt^2+\frac{1}{3}g_{\mathbb S^2}+\cosh^2(\sqrt{3}t)dx^2,
}
where $g_{\mathbb S^2}$ denotes the metric of constant curvature $1$, is known to be unstable \cite{Be09-1,Be09-2} and shares similar features with the critical solution in Theorem \ref{thm-1}, which has one constant factor and one expanding factor (as Nariai does).

Then, recall $x=\log(a)$ and $y=\log(b)$, the Einsteins equations imply the following system of ODEs:
\eq{\label{eq : wp-ev}\alg{
		x''&=n-\lambda_1e^{-2x}-n_1(x')^2-n_2x'y'\\
		y''&=n-\lambda_2e^{-2y}- n_2(y')^2-n_1x'y'
	}}
and the Hamiltonian constraint reduces to
\eq{n(n-1)=n_1\lambda_1e^{-2x}+n_2\lambda_2e^{-2y}+(n_1-1)n_1(x')^2+(n_2-1)n_2(y')^2+2n_1n_2x'y',}
where $x'$ denotes the time derivative of $x$.

A straightforward computation shows that the mean curvature $H$, the second fundamental form $K$ and the norm of the tracefree part $\Sigma$ of the latter are given by
\eq{\alg{
H&=-n_1x'-n_2y',\\
K&=-x'\cdot g_1-y'\cdot g_2,\\
|\Sigma|^2&= \frac{n_1n_2}{n}\cdot (x'-y')^2,
}}
respectively.

\label{sing-thm}
	Let $(\overline M^{n+1},\mathbf{g})$ be a $n+1$-dimensional globally hyperbolic Lorentzian manifold and suppose 
	\eq{Ric(X,X)\geq -n |\mathbf g(X,X)|}
	for all timelike vectors $X$. Assume furthermore that there exists a hypersurface $M$ whose expansion satisfies $\theta\leq \theta_0<-n$. Then, $(\overline M,\mathbf g)$ is future geodesically incomplete.

Let $g$ be the induced metric on $M$ and as above, let $K$ be the second fundamental form of $M$ and $\Sigma=K-\frac{1}{n}H$ its tracefree part. By the constraint equations, 
\eq{n(n-1)=R(g)-|K|^2+H^2=R(g)-|\Sigma|^2+\frac{n-1}{n}H^2\leq R_0+ \frac{n-1}{n}H^2,}
so that 
\eq{\theta^2=H^2\geq (n(n-1)-R_0)\frac{n}{n-1}>n^2.}
After time reflection, if necessary, we may conclude 
\eq{\theta\leq \theta_0<-n}
and now future incompleteness follows from the above singularity theorem.

\noindent
We first prove Case 1. By assumptions on the $\lambda_i$, $y''(0)=n-\lambda_2<0$ and $x''(0)=n-\lambda_1>\frac{n}{n_1}>0$. Then, $x$ is monotonically increasing: If $t_0>0$ is the first time such that $x'(t_0)=0$, we get $x''(t_0)>\frac{n}{n_1}>0$ (if $\lambda_1\leq0$, we even get $x''(t_0)\geq n)$ which implies $x'(t)<0$ for $t\in (t_0-\varepsilon,t_0)$ and thus contradicts the assumption. Analogously, one shows that $y$ is monotonically decreasing.

	Now we show that as long as $y$ is uniformly bounded, its derivatives exist and $x$ and its derivatives cannot blow up in finite time. If $y'\leq-1$ and $y\geq Y_0$, we obtain by monotonicity, the evolution equation and $x'y'<0$ that
	\eq{y''\geq -C (y')^2}
	which after dividing by $y'$ and integration in turn implies
	\eq{\log|y'|\leq C(1-Y_0),}
	i.e. $y'$ is bounded.
	Observe that by the evolution equation, we get $x''\leq n+Cx'$ as long as $y'>-C$ which implies the assertion on $x$. 

	Next we show that $y$ is unbounded. If not, it must converge to a limit by monotonicity, so we have $y(\infty)=\lim_{t\to\infty} y(t)$. Then we get either a sequence of $t_i\to\infty$ such that $y''(t_i)=0$ or $\lim_{t\to\infty} y''(t)=0$. The first case cannot occur, since then
	$y''(t_i)=n-\lambda_2e^{-2y(t_0)}\geq \frac{n}{n_1}>0$. In the latter case, we necessarily get $\lim x'(t)=\infty$ by the evolution of $y$. On the other hand, by the constraint equation,
	\eq{n_1x''-n_2y''=n(n_1-n_2)-n_1\lambda_1e^{-2x}+n_2\lambda_2e^{-2y}-n_1^2(x')^2+n_2^2(y')^2\\
		\leq C-n_1^2(x')^2+n_2^2(y')^2}
	From the constraint and adding the evolution equations, we also easily obtain
	\eq{n_1(x''+(x')^2)+n_2(y''+(y')^2)=n,} 
	from which we get
	\eq{-n_1(x')^2-2n_2y''+n-n_2(y')^2\leq C-n_1^2(x')^2+n_2^2(y')^2}
	and therefore, since $n_1>1$ (if $n_1=1$, the above bound implies $\lambda_1<0$ which in turn contradicts $n_1=1$), we get a bound on $x'$ if $y'$ and $y''$ are bounded. This yields the contradiction.

	By monotonicity of $x$ and $y$ and the unboundedness of $y$ from below there is a constant $C>0$ and a time $t_1>0$ such that the differential inequality 
	\eq{
		n_1x''+n_2y''\leq-C-(n_1x'+n_2y')^2
	}
	holds for all $t\geq t_1$. By ODE comparison,
	$z(t)=n_1x'(t)+n_2y'(t)\leq -\sqrt{C}\tan(D+\sqrt{C}(t-t_1))$ for $t\geq t_1$ and some $D\in\mathbb{R}$. Therefore, $z\to-\infty$ as $t$ approaches some $t_+$. As $x'>0$, $y'\to-\infty$. We also have $y(t)\leq\frac{1}{n_2}\int_0^{t}z(s)ds\to-\infty$ as $t\to t_+$, which implies that $y$ diverges.
	In addition, because
	\eq{x''=n-\lambda_1e^{-2x}-zx'\geq -zx',}
	we obtain $x(t)\geq \int_0^t\exp(-\int_0^sz(r)dr)ds\to \infty$ as $t\to t_+$.

It remains to show that the Kretschmann scalar is unbounded at the singularity:
 	 Let $0$ be the index referring to the $t$-coordinate and $i,j$ and $a,b$ be indices referring to coordinates on $M_1,M_2$ respectively. One can check that the coefficients with an odd number of zeros vanish and therefore, the Kretschmann scalar satisfies
 	\eq{ |\tilde{R}|^2=\tilde{R}_{\mu\nu\lambda\sigma}\tilde{R}^{\mu\nu\lambda\sigma}\geq 0}
 	because all summands are nonnegative. Now it can be checked that
 	\eq{ \tilde{R}_{0ij0}=-\frac{\partial^2_t a}{a} \tilde{g}_{ij},\qquad \tilde{R}_{0ab0}=-\frac{\partial^2_t b}{b} \tilde{g}_{ab},}
 	so that
 	\eq{|\tilde{R}|^2\geq \left(n_1\frac{\partial^2_t a}{a}\right)^2+n_2\left(\frac{\partial^2_t b}{b}\right)^2=n_1(x''+(x')^2)^2+n_2(y''+(y')^2)^2}
 	where as above $x=\log(a)$, $y=\log(b)$.
 	Now, since $x\to\infty$ as $t\to t_+$,
 we also get $x''+(x')^2\to\infty$, which shows that the Kretschmann scalar must blow up. This finishes the proof in Case 1. In Case 2, it is easy to see that the metric given in the statement of the theorem is the MGHD of the given initial data.







		Let us now consider Case 3. By assumption,
		\eq{
			y''(0)=n-\lambda_2\in(0,1)
		}
		and
		\eq{
			x''(0)=n-\lambda_1\in (1,\frac{n}{n_1}).
		}
		Both $x$ and $y$ are strictly monotonically increasing. We have $x'(t)>0$ for small $t$. Let $t_0$ be the first time, where $x'(t_0)=0$. Then  we obtain
		\eq{
			x''(t_0)=n-\lambda_1e^{-2x(t_0)}>0,
		}
		as long as $y'(t_0)$ exists. Thus $x'<0$ on $(t_0-\varepsilon,t_0)$, which causes the contradiction.
		Analogously one shows that $y$ is strictly monotonically increasing. From the evolution equations and monotonicity we deduce
		\eq{
			n^2-n_1\lambda_1-n_2\lambda_2-(n_1x'+n_2y')^2\leq n_1x''+n_2y''\leq n^2-(n_1x'+n_2y')^2.
		}
		The solution of the corresponding ODE, $z'=n^2-z^2$,
	 is $z(t)=n\tanh(nt+c)$, where $c\in \mathbb{R}$. By the initial conditions this implies $0<n_1x'+n_2y'<n$ for all $t>0$. Due to the positivity of $x'$ and $y'$ these statements hold for $x'$ and $y'$ individually.
		In particular, $x$ and $y$ exist for all times, which finishes the proof of Case 3.

Finally, recollapse of MGHDs of small perturbations of the initial data induced by the models follows by the Cauchy stability of the Einstein equations in combination with Theorem \ref{sing-thm}. As the background solutions have Cauchy surfaces of strictly positive and strictly negative mean curvature, this also holds for the MGHDs of small perturbations. Then the singularity theorem yields incompleteness. This idea of proof is explained in further detail originally in \cite{Ri09}. Stability in the expanding direction follows from the results in \cite{Ri08}.

\label{expansionrate}	With some more effort, we can determine the expansion rate of the warping factors of the  solutions appearing in Case 3:	
		By the above, we have $n_1x'(t)+n_2y'(t)>C_1>0$ for all $t\geq t_1$ and $n_1x(t)+n_2y(t)>C_2t$ for all $t\geq t_1$ and $C_2>0$. Using this, we can improve the above estimate. Denoting $z=n_1x'+n_2y'$ as above, we get
		\eq{
			n^2-Ce^{-Ct}-z^2\leq z'\leq n^2-z^2.
		}	
		from which we obtain the uniform bounds $0\geq z-n\geq -Ce^{-Ct}$. After integrating,
		\eq{\label{z}0\geq n_1x+n_2y-nt\geq -C.}
		Similarly, we obtain for $w:=n_1x'-n_2y'$ the estimate
		\eq{ n(n_1-n_2)-Ce^{-C t} -zw \leq w'\leq  n(n_1-n_2)+Ce^{-C t} -zw}
		which implies because of the estimate on $n-z$ that $|w-(n_1-n_2)|\leq Ce^{-Ct}$. Again by integrating,
		\eq{\label{w}{C_1\geq n_1x-n_2y-(n_1-n_2)t\geq C_2.}}	
		Finally, we obtain from \eqref{z} and \eqref{w} that $\sup \left\{|x-t|,|y-t|\right\}\leq C$. It is immediate that the warping functions satisfy $C_1 e^t\leq a(t) \leq C_2e^t$ and $C_1 e^t\leq b(t) \leq C_2e^t$ for $t\geq0$.

If $\lambda_1,\lambda_2\leq 0$, we are going to show that all corresponding solutions are geodesically incomplete in one direction and geodesically complete in the other.
	Let us first remark that the case where $R(g)\equiv |\Sigma|\equiv 0$ corresponds to the solution $-dt^2+e^{2t}g$ which is geodesically incomplete in the past and geodesically complete in the future. Therefore we assume $R(g)-|\Sigma|^2\leq R_0<0$ from now on.
		 By the constraint equation, we have 
		\eq{n(n-1)=R(g)-|K|^2+H^2=R(g)-|\Sigma|^2+\frac{n-1}{n}H^2\leq R_0+ \frac{n-1}{n}H^2,}
		As above, we get $|\theta|\geq \theta_0>n$. If $\theta\leq-\theta_0<-n$, we obtain geodesic incompleteness by Proposition \ref{sing-thm}. If $\theta\geq\theta_0>n$, we have the differential inequality
			\eq{ \partial_t \theta\leq n-\frac{1}{n}\theta^2}
	so that we have the upper bound
			\eq{\theta \leq n\cdot\frac{e^{2t}-A_0}{e^{2t}+A_0}= \frac{n}{1-|A_0|e^{-2t}}(1+|A_0|e^{-2t})\leq n+n|A_0|e^{-2t}}
		where $A_0=\frac{n-\theta_0}{n+\theta_0}$. Again by the constraint equation,
		\eq{0\leq-R(g)+|\Sigma|^2= \frac{n-1}{n}(\theta^2-n^2)\leq Ce^{-2t}. }
		In particular, since $R(g)=n_1\lambda_1e^{-2x}+n_2\lambda_2 e^{-2y}$, both factors $x,y$ grow linearly, in particular, they do not converge to $-\infty$. Thus, they are geodesically complete.

We have the data $n_1=2$, $n_2=1$, $\lambda_1=\lambda$, $\lambda_2=0$, so the evolution equations are
\eq{\alg{x''&=3-\lambda e^{-2x}-2(x')^2-x'y'\\
	y''&=3-(y')^2-2x'y'}}
and the constraint equation reduce to
\eq{6=2\lambda e^{-2x}+2(x')^2+4x'y'.}
We demand $y'(0)=0$ such that we obtain a one-parameter family of solutions by prescribing $\lambda$ and $x'(0)$ such that
\eq{3=\lambda+(x'(0))^2}
by the constraint. Recall that we generally require $x(0)=0$. For our purposes, we additionally assume $\lambda>0$ throughout.
 By using the constraint, the equation on $x$ decouples as
\eq{\alg{x''&=3-\lambda e^{-2x}-2(x')^2-x'y'=\frac{1}{2}(3-\lambda e^{-2x}-3(x')^2).}}
Now we show that the MGHD is future incomplete, if $\lambda<3$ and $x'(0)<0$. At first,
\eq{x''(0)=3-\lambda-2x'(0)^2=(3-\lambda-(x'(0))^2)-x'(0)^2<0,}
which shows that both $x$ and $x'$ are monotonically decreasing for small time. In addition, as long as $x$ and $x'$ are monotonically decreasing, we have
\eq{x''=\frac{1}{2}(3-\lambda e^{-2x}-3(x')^2)\leq\frac{1}{2}(3-\lambda-2(x'(0)))\leq \frac{1}{2}x''(0)<0,}
which shows that this monotonicity property holds for all time and $x$ and $x'$ are unbounded. In particular, for large time, we get
\eq{x''\leq -\frac{3}{2}(x')^2. }
This shows that $x'\to -\infty$ as $t$ approaches some $t_+$, since the comparison ODE is solved by $z(t)=\frac{2}{c+3t}$. By integrating, one obtains the estimate
\eq{x(t)\leq C_1+\log(C_2-\frac{3}{2}t)}
for some constants  $C_1,C_2>0$ which shows that also $x\to-\infty$ as $t\to t_+$.

We are also able to show that this singularity is of Kasner type, i.e. $y(t)\to\infty$ as $t\to t_+$. At first note that $y$ is monotonically increasing for small time. In fact, it is monotonically increasing for all $t>0$ since $y''(t_0)=3>0$ as long as $y'(t_0)=0$. But then we have an estimate 
\eq{y'' \geq 3-(y')^2+2 |z|y'}
and since $z\to\infty$ as $t\to t_+$ this shows that $y'\to\infty$ as $t\to t_+$ and because the integral of $z$ diverges, we get that also $y$ diverges as $t\to t_+$.
